interface Cart {
  id: string;
  lines: { sku: string; quantity: number; priceKobo: number }[];
}

type CartLine = Cart["lines"][number];

function lineTotal(line: CartLine): number {
  return line.quantity * line.priceKobo;
}

const cart: Cart = {
  id: "CART-9",
  lines: [
    { sku: "TOTE-01", quantity: 2, priceKobo: 450_000 },
    { sku: "MUG-07", quantity: 4, priceKobo: 180_000 },
  ],
};
console.log(cart.lines.reduce((sum, line) => sum + lineTotal(line), 0));

