function describeFields<T extends object>(item: T, keys: readonly (keyof T & string)[]): string {
  return keys.map((key) => `${key}=${String(item[key])}`).join(", ");
}

const invoice = { number: "INV-0042", totalKobo: 1_500_000, paid: false };
